 void FrameArena(float dt){if(arenaFraming==null)arenaFraming=broadcast.GetComponent<SportsCameraFit>();var desired=new Bounds(new Vector3(0,2,0),new Vector3(arenaX*2+2,6,arenaZ*2+2));if(Running){for(int i=0;i<setup.count;i++)if(alive[i])desired.Encapsulate(trucks[i].shape.bounds);desired.Encapsulate(ball.position+Vector3.up*1.5f);}if(!arenaFrameReady){arenaFrame=desired;arenaFrameReady=true;}float blend=1-Mathf.Exp(-Mathf.Max(0,dt)*2.5f);arenaFrame.center=Vector3.Lerp(arenaFrame.center,desired.center,blend);var margin=desired.center-arenaFrame.center;margin=new Vector3(Mathf.Abs(margin.x),Mathf.Abs(margin.y),Mathf.Abs(margin.z));arenaFrame.extents=Vector3.Max(Vector3.Lerp(arenaFrame.extents,desired.extents,blend),desired.extents+margin);broadcast.Pose(arenaFrame.center,new Vector3(0,42,-26),60);if(arenaFraming!=null){arenaFraming.arenaBounds=arenaFrame;arenaFraming.topInset=.12f;arenaFraming.Apply();}}
