 public float respawnDelay=2,respawnProtection=1.1f,stealProtection=.8f,minimumApproach=2.1f,arenaX=22,arenaZ=18;public int Carrier{get;private set;}=-1;public int Winner{get;private set;}=-1;public int Steals{get;private set;}public int Pickups{get;private set;}public int Blasts{get;private set;}public float[] possession=new float[4];public float Target=>option==0?30:option==1?60:90;
 public readonly bool[] alive=new bool[4];public readonly float[] shield=new float[4];readonly float[] returnAt=new float[4],blastUntil=new float[4],stalled=new float[4],reactAt=new float[4],backing=new float[4];readonly float[] aiStall=new float[4],progressWindow=new float[4],recoverySteer=new float[4];readonly int[] aiCarrier=new int[4];readonly Vector3[] aiPrevious=new Vector3[4];readonly Vector3[] incoming=new Vector3[4],incomingPosition=new Vector3[4],previous=new Vector3[4],targets=new Vector3[4];readonly bool[] touching=new bool[16];readonly float[] challenges=new float[4];readonly Collider[] overlaps=new Collider[48];uint pickupMask;float heldShield,noticeUntil,nextIdentity;int effectIndex;string notice="CHASE THE BALL";Vector3 lastReachable;readonly StringBuilder text=new StringBuilder(800);
 public override string Title=>cabVariant?"KEEPAWAY · FIRST PERSON":"KEEPAWAY · ARENA VIEW";public override int MinimumPlayers=>2;public override int MaximumPlayers=>4;public override bool UsesAction=>false;public override string OptionLabel=>Target+" SECONDS · CUMULATIVE POSSESSION";
 public override string Help=>"TRUCK KEEPAWAY · CUMULATIVE POSSESSION\nArena View or human-only split-screen First Person; AI-only uses broadcast. Random/explicit weather, Lively chaos and reproducible match seeds. Rounded boards keep chases flowing around the corners. Ramps, rotating sweepers, loose tires, mud and wandering SheepV5 vary the connected chase routes. Sheep blasts can knock you away or wreck your truck; a wrecked carrier drops the single ball, surviving carriers retain possession. Chains/effects are bounded and sheep replenish away from trucks.\n\nTwo to four competitors. First to hold the ball for a TOTAL of 30 / 60 / 90 seconds wins (default60). Your time persists after every steal; it need not be one uninterrupted hold.\n\nDrive using the source shown in setup. Reverse input brakes before reversing. Touch the neutral physical ball to collect it. A meaningful fresh truck-body hit INTO the carrier steals it. Coasting overlap and merely being rammed by the carrier do not steal. Simultaneous equal challenges leave ownership unchanged.\n\nOwnership transfers atomically before the former carrier explodes. The thief receives short visible steal/blast protection. Debris and blast-induced collisions never steal or recursively explode carriers. The same pair must separate before another steal.\n\nWrecked trucks respawn after about two seconds at a clear location. White protection rings prevent free pickup/steals until they expire; they are not an offensive shield. Other trucks remain live. Escaping the arena or genuinely becoming immobile/overturned triggers a fair return, dropping any carried ball in a reachable clear area. Possession pauses while recovering.\n\nAI uses the same NWH drive and body-contact rules: the carrier selects open routes while challengers intercept. Pause/disconnect freezes time and preserves every body, score and respawn clock. Rematch keeps configuration. Each seed selects rocky Cheese mud, snow, beach sand or meadow ground. Timber ramps, crates, barrels, tires and striped steel sweepers are physical obstacles. Offline only; no permanent elimination.";
 public override string Header=>Title+"  ·  FIRST TO "+Target+"s TOTAL POSSESSION";
 public override string Status=>Time.time<noticeUntil?notice:Carrier>=0?setup.players[Carrier].name+" HAS THE BALL  ·  "+Mathf.Max(0,Target-possession[Carrier]).ToString("F1")+"s TO WIN":"NEUTRAL BALL · TOUCH TO COLLECT";
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++){text.Append(i==Carrier?"● ":"  ").Append(setup.players[i].name).Append("   ").Append(possession[i].ToString("F1")).Append(" / ").Append(Target).Append("s").Append(alive[i]?shield[i]>Time.time?"  PROTECTED":"":"  RESPAWNING").Append(i==setup.count-1?"":"    |    ");}return text.ToString();}}
 public override string Results=>setup.players[Winner].name+" WINS\n\n"+Standings+"\n"+Steals+" STEALS · "+Blasts+" COMIC EXPLOSIONS";
 protected override void BeginGame(){matchAge=0;chaosField.chaos=chaosLevel;chaosField.weatherChoice=weatherChoice;chaosField.NewLayout(unchecked(layoutSeed+matchNumber++*997));LayoutViews();Carrier=Winner=-1;Steals=Pickups=Blasts=effectIndex=0;pickupMask=0;heldShield=0;Array.Clear(possession,0,4);Array.Clear(touching,0,16);Array.Clear(challenges,0,4);for(int i=0;i<4;i++){trucks[i].gameObject.SetActive(i<setup.count);trucks[i].visuals.gameObject.SetActive(i<setup.count);alive[i]=i<setup.count;shield[i]=blastUntil[i]=stalled[i]=reactAt[i]=backing[i]=0;if(i>=setup.count)continue;var p=new Vector3(i%2==0?-27:27,.48f,i<2?-11:11);trucks[i].slot=i;trucks[i].Prepare(p,Quaternion.LookRotation(-new Vector3(p.x,0,p.z)));ResetPlanner(i,p);previous[i]=p;incoming[i]=Vector3.zero;incomingPosition[i]=p;}foreach(var d in debris){d.body.isKinematic=true;d.gameObject.SetActive(false);}foreach(var fx in explosions)fx.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);Drop(new Vector3(0,.85f,0));notice="CHASE THE BALL · "+chaosField.ground.Description+" · "+chaosField.weather.Description;noticeUntil=Time.time+3;}
 void LayoutViews(){arenaFrameReady=false;broadcast.view.rect=new Rect(0,0,1,1);HumanViews=SportsCameraOptions.Select(setup,cameraSlots);bool cab=cabVariant&&HumanViews>0;broadcast.view.enabled=!cab;for(int i=0;i<4;i++){cabViews[i].view.enabled=cab&&i<HumanViews;if(i<HumanViews){cabViews[i].view.rect=LWS.TruckCornhole.CornholeMatch.ViewRect(HumanViews,i);cabHeading[i]=Quaternion.identity;}}cameras=cab?new Camera[HumanViews]:new[]{broadcast.view};chaosField.weather.vendor.AllowCameras.Clear();if(cab){for(int i=0;i<HumanViews;i++){cameras[i]=cabViews[i].view;chaosField.weather.vendor.AllowCameras.Add(cameras[i]);}}else chaosField.weather.vendor.AllowCameras.Add(broadcast.view);}
 public override string ViewText(int view){int slot=cameraSlots[view];var focus=Carrier>=0?trucks[Carrier].body.position:ball.position;var delta=focus-trucks[slot].body.position;var local=Quaternion.Inverse(cabHeading[view])*delta;string direction=Mathf.Abs(local.x)>Mathf.Abs(local.z)?local.x>0?"RIGHT":"LEFT":local.z>0?"AHEAD":"BEHIND";text.Clear().Append("<color=#").Append(ColorUtility.ToHtmlStringRGB(setup.players[slot].color)).Append(">").Append(setup.players[slot].name).Append("</color>  ").Append(possession[slot].ToString("F1")).Append('/').Append(Target).Append("s\n");if(!alive[slot])text.Append("WRECKED · RESPAWNING");else if(Carrier==slot)text.Append("YOU HAVE THE BALL · KEEP MOVING");else text.Append(Carrier>=0?setup.players[Carrier].name:"LOOSE BALL").Append(" · ").Append(direction).Append(' ').Append(delta.magnitude.ToString("F0")).Append('m');if(shield[slot]>Time.time)text.Append(" · PROTECTED");text.Append('\n');for(int i=0;i<setup.count;i++)text.Append(i==0?"":"  ").Append("P").Append(i+1).Append(' ').Append(possession[i].ToString("F0")).Append('s');return text.ToString();}
 public int CabSlot(int view)=>cameraSlots[Mathf.Clamp(view,0,3)];
 public bool CanAttack(int i)=>Live&&i>=0&&i<setup.count&&alive[i]&&Time.time>=shield[i]&&Time.time>=blastUntil[i];
 public void Pickup(int slot){if(Carrier<0&&CanAttack(slot))pickupMask|=1u<<slot;}
 public void Separate(int a,int b){touching[Mathf.Min(a,b)*4+Mathf.Max(a,b)]=false;}
 public void Collision(int a,int b,Vector3 point){if(!Live||a==b)return;int key=Mathf.Min(a,b)*4+Mathf.Max(a,b);if(touching[key])return;touching[key]=true;if(Carrier!=a&&Carrier!=b||Time.time<heldShield)return;int challenger=Carrier==a?b:a;if(!CanAttack(challenger)||!alive[Carrier])return;var n=incomingPosition[Carrier]-incomingPosition[challenger];n.y=0;if(n.sqrMagnitude<.1f)return;n.Normalize();float approach=Vector3.Dot(incoming[challenger],n),closing=Vector3.Dot(incoming[challenger]-incoming[Carrier],n);if(approach>=minimumApproach&&closing>=minimumApproach)challenges[challenger]=Mathf.Max(challenges[challenger],closing);}
 void Claim(int slot,bool steal){int former=Carrier;Carrier=slot;ball.isKinematic=true;ballShape.enabled=false;trail.Clear();heldShield=Time.time+stealProtection;if(steal){Steals++;Explode(former,slot);notice="STEAL · "+setup.players[slot].name;}else{Pickups++;notice=setup.players[slot].name+" COLLECTED THE BALL";}noticeUntil=Time.time+1.3f;Pulse(slot,.3f,.13f);feedback.Play(4,0,true);Debug.Log("KEEPAWAY_OWNERSHIP carrier="+Carrier+" former="+former+" steal="+steal);}
 void ResolveContacts(){if(Carrier<0&&pickupMask!=0){int chosen=-1;float best=float.PositiveInfinity;bool tie=false;for(int i=0;i<setup.count;i++)if((pickupMask&(1u<<i))!=0&&CanAttack(i)){float d=(incomingPosition[i]-ball.position).sqrMagnitude;if(d<best-.001f){best=d;chosen=i;tie=false;}else if(Mathf.Abs(d-best)<.001f)tie=true;}if(chosen>=0&&!tie)Claim(chosen,false);}pickupMask=0;if(Carrier>=0&&Time.time>=heldShield){int chosen=-1;float best=0;bool tie=false;for(int i=0;i<setup.count;i++)if(CanAttack(i)){float c=challenges[i];if(c>best+.001f){best=c;chosen=i;tie=false;}else if(c>0&&Mathf.Abs(c-best)<.001f)tie=true;}if(chosen>=0&&!tie)Claim(chosen,true);}Array.Clear(challenges,0,4);}
 void Drop(Vector3 p){Carrier=-1;ballShape.enabled=true;ball.isKinematic=false;ball.position=ClearBall(p);ball.linearVelocity=ball.angularVelocity=Vector3.zero;trail.Clear();heldShield=Time.time+.15f;}
 Vector3 ClearBall(Vector3 request){for(int k=0;k<40;k++){float a=k*2.39996f;float r=k==0?0:1.5f+k*.35f;var p=new Vector3(Mathf.Clamp(request.x+Mathf.Cos(a)*r,-arenaX+3,arenaX-3),.85f,Mathf.Clamp(request.z+Mathf.Sin(a)*r,-arenaZ+3,arenaZ-3));bool clear=chaosField==null||chaosField.Reachable(p);foreach(var c in obstacles)if(c!=null&&c.gameObject.activeInHierarchy&&Vector3.Distance(NearPoint(c,p),p)<1.2f){clear=false;break;}if(clear)return p;}return new Vector3(0,.85f,0);}
 void Explode(int former,int thief){if(former<0||!alive[former])return;if(Carrier==former)Drop(lastReachable);Blasts++;var source=trucks[former];var origin=source.body.position;alive[former]=false;returnAt[former]=Time.time+respawnDelay;source.Park(origin);source.visuals.gameObject.SetActive(false);var fx=explosions[effectIndex++%explosions.Length];fx.transform.position=origin;fx.Play();feedback.Play(2,0,true);
  for(int j=0;j<8;j++){var bit=debris[(Blasts*8+j)%debris.Length];bit.Emit(origin+Vector3.up*(.5f+j*.06f));var direction=Quaternion.Euler(0,j*45,0)*new Vector3(1,.7f,0);bit.body.AddForce(direction.normalized*(7+j*.35f),ForceMode.VelocityChange);bit.body.AddTorque(new Vector3(2,j*.3f,3),ForceMode.VelocityChange);}
  for(int i=0;i<setup.count;i++)if(i!=thief&&alive[i]){var t=trucks[i];var delta=t.body.worldCenterOfMass-origin;float distance=delta.magnitude;if(distance>17)continue;delta.y=Mathf.Max(2.3f,delta.y+3);float strength=Mathf.Lerp(17,2,Mathf.Clamp01(distance/17));t.body.AddForce(delta.normalized*strength,ForceMode.VelocityChange);t.body.AddTorque(new Vector3(strength*.07f,0,strength*.09f),ForceMode.VelocityChange);blastUntil[i]=Time.time+.9f;Pulse(i,.4f,.2f);}
 }
 bool SpawnPoint(int slot,out Vector3 point){for(int k=0;k<32;k++){float a=(k+slot*7)*2.39996f;var p=new Vector3(Mathf.Cos(a)*(arenaX-4),.48f,Mathf.Sin(a)*(arenaZ-4));bool good=KeepawayBoundary.Contains(p,2.4f)&&chaosField.Reachable(p);for(int i=0;i<setup.count;i++)if(i!=slot&&alive[i]&&Vector3.Distance(trucks[i].body.position,p)<4.5f){good=false;break;}if(!good)continue;int n=Physics.OverlapSphereNonAlloc(p,2.2f,overlaps,1,QueryTriggerInteraction.Ignore);for(int i=0;i<n;i++)if(Array.IndexOf(obstacles,overlaps[i])>=0){good=false;break;}if(n==overlaps.Length)good=false;if(good){point=p;return true;}}point=Vector3.zero;return false;}
 void Recover(int i){if(Carrier==i)Drop(lastReachable);alive[i]=false;returnAt[i]=Time.time+.3f;trucks[i].Park(trucks[i].body.position);trucks[i].visuals.gameObject.SetActive(false);}
 protected override void Simulate(float dt){matchAge+=dt;chaosField.Step(dt);ResolveContacts();for(int i=0;i<setup.count;i++){if(!alive[i]){if(Time.time>=returnAt[i]&&SpawnPoint(i,out var spawn)){trucks[i].visuals.gameObject.SetActive(true);trucks[i].Prepare(spawn,Quaternion.LookRotation(new Vector3(-spawn.x,0,-spawn.z)));shield[i]=Time.time+respawnProtection;blastUntil[i]=0;stalled[i]=0;alive[i]=true;ResetPlanner(i,spawn);previous[i]=spawn;for(int j=0;j<4;j++)Separate(i,j);}continue;}var t=trucks[i];var p=t.body.position;bool outside=!KeepawayBoundary.Contains(p,-3)||p.y< -3||p.y>25;if(outside){Recover(i);continue;}if((p-previous[i]).sqrMagnitude<.0004f&&Vector3.Dot(t.transform.up,Vector3.up)<.4f)stalled[i]+=dt;else stalled[i]=Mathf.Max(0,stalled[i]-dt);previous[i]=p;if(stalled[i]>4){Recover(i);continue;}if(Carrier==i){lastReachable=ClearBall(p);possession[i]=Mathf.Min(Target,possession[i]+dt);if(possession[i]>=Target){Winner=i;EndMatch();return;}}Vector2 drive=commands[i];if(setup.players[i].source==BowlingSource.AI)drive=AI(i,dt);t.grip=1.4f*chaosField.SurfaceGrip(p);t.TickDrive(drive);t.body.AddForce(chaosField.weather.Flow*(t.Grounded?.25f:.6f),ForceMode.Acceleration);incoming[i]=t.body.linearVelocity;incomingPosition[i]=p;}
  if(Carrier<0&&!ball.isKinematic)ball.AddForce(chaosField.weather.Flow*.3f,ForceMode.Acceleration);if(Carrier>=0)ball.MovePosition(trucks[Carrier].body.position+Vector3.up*1.9f);else if(ball.position.y< -2||!KeepawayBoundary.Contains(ball.position,-.7f))Drop(Vector3.zero);
 }
 void ResetPlanner(int i,Vector3 position){routeAt[i]=reactAt[i]=backing[i]=aiStall[i]=progressWindow[i]=0;aiPrevious[i]=position;waypoints[i]=targets[i]=Vector3.zero;aiCarrier[i]=int.MinValue;}
 static Vector3 NearPoint(Collider shape,Vector3 point)=>shape is MeshCollider mesh&&!mesh.convex?shape.ClosestPointOnBounds(point):shape.ClosestPoint(point);
 Vector2 AI(int i,float dt){var t=trucks[i];var p=t.body.position;if(backing[i]>0){backing[i]=Mathf.Max(0,backing[i]-dt);aiPrevious[i]=p;progressWindow[i]=aiStall[i]=0;if(backing[i]<=0)routeAt[i]=reactAt[i]=0;return new Vector2(recoverySteer[i],-.75f);}bool applyingMotor=Mathf.Abs(t.command.y)>.3f&&Mathf.Abs(t.wheels[0].MotorTorque)>.05f&&t.wheels[0].BrakeTorque<.1f;if(!applyingMotor){aiPrevious[i]=p;progressWindow[i]=0;}else{progressWindow[i]+=dt;if(progressWindow[i]>=.75f){float progress=Vector3.ProjectOnPlane(p-aiPrevious[i],Vector3.up).magnitude;aiStall[i]=progress<.55f?aiStall[i]+progressWindow[i]:0;aiPrevious[i]=p;progressWindow[i]=0;}}if(aiStall[i]>=1.5f){backing[i]=1.1f;recoverySteer[i]=Mathf.Abs(t.command.x)>.15f?-Mathf.Sign(t.command.x)*.8f:i%2==0?.8f:-.8f;aiStall[i]=0;return new Vector2(recoverySteer[i],-.75f);}if(aiCarrier[i]!=Carrier){aiCarrier[i]=Carrier;reactAt[i]=routeAt[i]=0;}
  var level=setup.players[i].difficulty;float reaction=level==BowlingDifficulty.Easy?.38f:level==BowlingDifficulty.Normal?.2f:.09f;if(Time.time>=reactAt[i]){if(Carrier==i){float best=-999;for(int k=0;k<12;k++){float a=k*Mathf.PI/6;var candidate=new Vector3(Mathf.Cos(a)*(arenaX-5),.4f,Mathf.Sin(a)*(arenaZ-5));float nearest=999;for(int j=0;j<setup.count;j++)if(i!=j&&alive[j])nearest=Mathf.Min(nearest,Vector3.Distance(candidate,trucks[j].body.position));float cost=nearest-Vector3.Distance(candidate,p)*.12f;if(cost>best){best=cost;targets[i]=candidate;}}}else targets[i]=Carrier>=0?trucks[Carrier].body.position+trucks[Carrier].body.linearVelocity*(level==BowlingDifficulty.Hard?.65f:level==BowlingDifficulty.Normal?.4f:.15f):ball.position;targets[i]+=new Vector3(UnityEngine.Random.Range(-1f,1f),0,UnityEngine.Random.Range(-1f,1f))*(level==BowlingDifficulty.Easy?1.8f:.4f);reactAt[i]=Time.time+reaction;}
  if(Time.time>=routeAt[i]){waypoints[i]=chaosField.Route(p,targets[i]);routeAt[i]=Time.time+.15f;}var delta=waypoints[i]-p;delta.y=0;foreach(var obstacle in obstacles){if(obstacle==null||!obstacle.gameObject.activeInHierarchy)continue;var near=NearPoint(obstacle,p+delta.normalized*3);var d=p-near;d.y=0;if(d.magnitude<3.5f&&d.sqrMagnitude>.01f)delta+=d.normalized*Mathf.Min((3.5f-d.magnitude)*3,Mathf.Min(6,delta.magnitude*.6f));}
  float angle=Vector3.SignedAngle(t.transform.forward,delta,Vector3.up);bool reverse=Mathf.Abs(angle)>115;if(reverse)angle=Mathf.DeltaAngle(0,angle-180);float gas=Mathf.Abs(angle)>65?.6f:1;if(delta.magnitude<1)gas=.4f;return new Vector2(Mathf.Clamp(angle/32,-1,1)*(reverse?-1:1),gas*(reverse?-1:1));
 }
 protected override void Present(float dt){if(trucks==null||broadcast==null)return;bool refresh=Time.unscaledTime>=nextIdentity;if(refresh)nextIdentity=Time.unscaledTime+.1f;FrameArena(dt);if(cabVariant&&HumanViews>0)for(int view=0;view<HumanViews;view++){int slot=cameraSlots[view];var t=trucks[slot];cabViews[view].cabSteering?.Bind(t);var f=Vector3.ProjectOnPlane(t.transform.forward,Vector3.up);if(f.sqrMagnitude>.1f&&Vector3.Dot(t.transform.up,Vector3.up)>.2f)cabHeading[view]=Quaternion.Slerp(cabHeading[view],Quaternion.LookRotation(f),1-Mathf.Exp(-dt*7));if(alive[slot]){var camera=cabViews[view].view;camera.cullingMask=(~(1<<(22+slot)))&~(15<<26)|(1<<(26+view));camera.fieldOfView=82;camera.transform.SetPositionAndRotation(t.body.position+Vector3.up*1.05f+cabHeading[view]*new Vector3(-.25f,0,1.08f),cabHeading[view]);}else{cabViews[view].view.cullingMask=~(15<<26);cabViews[view].Pose(t.body.position,new Vector3(4,3,-5),68);}}for(int i=0;i<4;i++){bool active=i<setup.count;halos[i].gameObject.SetActive(active&&alive[i]);identities[i].gameObject.SetActive(active&&alive[i]);if(!active)continue;var p=trucks[i].body.position;halos[i].position=new Vector3(p.x,.06f,p.z);halos[i].localScale=Vector3.one*(i==Carrier?2.8f:shield[i]>Time.time?2.3f:1.8f);identities[i].transform.position=p+Vector3.up*2.7f;if(!cabVariant)identities[i].transform.rotation=broadcast.transform.rotation;if(refresh)identities[i].text=setup.players[i].name+(i==Carrier?" · BALL":shield[i]>Time.time?" · PROTECTED":"");identities[i].color=i==Carrier?Color.yellow:shield[i]>Time.time?Color.white:setup.players[i].color;}}
 public void HazardBlast(Vector3 origin){var fx=explosions[effectIndex++%explosions.Length];fx.transform.position=origin;fx.Play();feedback.Play(2,0,true);for(int i=0;i<setup.count;i++){if(!alive[i]||Time.time<shield[i])continue;var t=trucks[i];var delta=t.body.worldCenterOfMass-origin;float distance=delta.magnitude;if(distance>16)continue;if(distance<3.2f){Explode(i,-1);continue;}delta.y=Mathf.Max(4,delta.y+4);float strength=Mathf.Lerp(22,3,distance/16);t.body.AddForce(delta.normalized*strength,ForceMode.VelocityChange);t.body.AddTorque(new Vector3(strength*.12f,.4f,strength*.15f),ForceMode.VelocityChange);blastUntil[i]=Time.time+.85f;Pulse(i,.45f,.2f);}}
 protected override void SetPaused(bool paused){chaosField?.Pause(paused);}
 protected override void StopGame(){if(trucks!=null)foreach(var t in trucks){t.Power(false);if(!t.body.isKinematic)t.body.linearVelocity=t.body.angularVelocity=Vector3.zero;t.body.isKinematic=true;}}
 protected override void StopSounds(){if(trucks!=null)foreach(var t in trucks)t.StopSound();}
}
